Modal: captured free component source. Dialog over a dimmed page with a header, scrolling body and actions, plus an alert dialog for destructive confirms.

Primary source: components/base/modal/modal.tsx. Exported names: ModalSize, useModalClose, ModalTriggerProps, ModalTrigger, ModalProps, Modal, ModalDialogProps, ModalDialog, ModalHeaderProps, ModalHeader, ModalBodyProps, ModalBody, ModalFooter, AlertDialogProps, AlertDialog.

Declared npm dependencies: @remixicon/react@^4.9.0, react-aria-components@^1.17.0.

BoardUI registry dependencies: button, close-button, cx, direction, scroll-fade, spinner. These names refer to source registry items, not npm packages.

Types from the primary source (referenced types may be imported):

```tsx
type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

export type ModalSize = "sm" | "md" | "lg" | "xl";

interface ModalContextValue {
  descriptionId: string;
  setDescribed: (described: boolean) => void;
}

export interface ModalTriggerProps extends Omit<DialogTriggerProps, "children"> {
  /**
   * The trigger, then the Modal (or AlertDialog). The trigger can be any
   * BoardUI button: anything that forwards its ref and spreads its props.
   * React Aria's own Button already speaks to DialogTrigger; use that
   * directly instead of wrapping it here.
   */
  children: ReactNode;
}

export interface ModalProps extends Omit<ModalOverlayProps, "children" | "className" | "style"> {
  /** Panel width: 400, 480 (default), 640, or 800px. */
  size?: ModalSize;
  /** `alertdialog` for confirmations that interrupt the user; see AlertDialog. */
  role?: "dialog" | "alertdialog";
  /** Accessible name when the content has no ModalHeader title. */
  "aria-label"?: string;
  /** Classes on the panel surface (the dialog). */
  className?: string;
  /** Classes on the full-screen overlay, e.g. to align the panel to the top. */
  overlayClassName?: string;
  children: ReactNode | ((renderProps: DialogRenderProps) => ReactNode);
}

export interface ModalDialogProps {
  role?: "dialog" | "alertdialog";
  "aria-label"?: string;
  /** Classes merged onto the panel surface. */
  className?: string;
  children: ReactNode | ((renderProps: DialogRenderProps) => ReactNode);
}

export interface ModalHeaderProps {
  title: ReactNode;
  /** Supporting copy under the title; announced as the dialog's description. */
  description?: ReactNode;
  /** Remix Icon shown in a 40px circle above the title. */
  icon?: IconComponent;
  /** `danger` tints the icon circle for destructive dialogs. */
  tone?: "default" | "danger";
  /** Show the dismiss button in the top corner. Default true. */
  showCloseButton?: boolean;
  closeLabel?: string;
  className?: string;
  /** Extra content under the description, e.g. tabs or a step indicator. */
  children?: ReactNode;
}

export interface ModalBodyProps {
  /** Classes on the scrolling region (it carries px-6 by default). */
  className?: string;
  children: ReactNode;
}

export interface AlertDialogProps
  extends Omit<ModalProps, "children" | "role" | "aria-label" | "isDismissable"> {
  title: ReactNode;
  description?: ReactNode;
  /** `danger` (default) pairs a tinted warning icon with a danger confirm button. */
  variant?: "danger" | "default";
  /** Leading icon; `false` hides it. Defaults to a warning glyph. */
  icon?: IconComponent | false;
  confirmLabel?: ReactNode;
  cancelLabel?: ReactNode;
  /**
   * Runs on confirm. Return a promise to keep the dialog open until it
   * settles: Cancel is disabled, and the confirm button turns busy with a
   * spinner and `pendingLabel`. It closes on success and stays open if the
   * promise rejects.
   */
  onConfirm?: () => void | Promise<unknown>;
  onCancel?: () => void;
  /** Confirm-button label while an async `onConfirm` runs. */
  pendingLabel?: ReactNode;
  /** Disables the confirm action, e.g. until a confirmation phrase is typed. */
  isConfirmDisabled?: boolean;
  /** Close on a backdrop press. Off by default: an alert asks for an answer. */
  isDismissable?: boolean;
  /** Extra content between the description and the actions. */
  children?: ReactNode;
}
```

Published usage example:

```tsx
import { RiMailLine, RiUserAddLine } from "@remixicon/react";
import { Button } from "@/components/base/buttons/button";
import { Input } from "@/components/base/input/input";
import { Modal, ModalBody, ModalFooter, ModalHeader, ModalTrigger } from "@/components/base/modal/modal";
import { Select, SelectItem } from "@/components/base/select/select";

export function Example() {
  return (
    <ModalTrigger>
      <Button leadingIcon={RiUserAddLine}>Invite teammates</Button>
      <Modal>
        {({ close }) => (
          <>
            <ModalHeader
              title="Invite teammates"
              description="They get an email with a link to join the Acme workspace."
            />
            <ModalBody>
              <form id="invite-form" className="flex flex-col gap-4" onSubmit={(event) => { event.preventDefault(); close(); }}>
                <Input label="Email address" type="email" placeholder="name@company.com" leadingIcon={RiMailLine} isRequired />
                <Select label="Role" defaultSelectedKey="member" className="gap-1.5" triggerClassName="w-full" popoverClassName="w-(--trigger-width)">
                  <SelectItem id="admin" textValue="Admin">Admin</SelectItem>
                  <SelectItem id="member" textValue="Member">Member</SelectItem>
                  <SelectItem id="viewer" textValue="Viewer">Viewer</SelectItem>
                </Select>
              </form>
            </ModalBody>
            <ModalFooter>
              <Button variant="secondary" onClick={close}>Cancel</Button>
              <Button type="submit" form="invite-form">Send invite</Button>
            </ModalFooter>
          </>
        )}
      </Modal>
    </ModalTrigger>
  );
}
```

This is API evidence, not an executable preview. Complete implementation and theme/dependency setup remain at https://www.boardui.com/r/modal.json and https://www.boardui.com/installation.

