Popover: captured free component source. Free-form content anchored to a trigger, with an optional arrow, smart positioning and the menu family's motion, built on React Aria.

Primary source: components/base/popover/popover.tsx. Exported names: PopoverTriggerProps, PopoverTrigger, PopoverProps, Popover, PopoverHeaderProps, PopoverHeader, PopoverFooter.

Declared npm dependencies: react-aria-components@^1.17.0.

BoardUI registry dependencies: cx, direction, tooltip, use-dismiss-on-outside-press. These names refer to source registry items, not npm packages.

Types from the primary source (referenced types may be imported):

```tsx
interface PopoverContextValue {
  popoverRef: RefObject<HTMLElement | null>;
}

export interface PopoverTriggerProps {
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  /**
   * The trigger, then the Popover. The trigger can be any BoardUI button:
   * anything that forwards its ref and spreads its props.
   */
  children: ReactNode;
}

export interface PopoverProps
  extends Pick<AriaPopoverProps, "placement" | "offset" | "crossOffset" | "shouldFlip" | "containerPadding" | "triggerRef" | "isOpen" | "onOpenChange"> {
  /** Draw a caret pointing at the trigger. */
  showArrow?: boolean;
  /** Accessible name when the content has no PopoverHeader title. */
  "aria-label"?: string;
  /** Classes on the surface, e.g. a width (default 320px). */
  className?: string;
  /** Classes on the inner dialog; `p-0` suits menu-like rows that pad themselves. */
  dialogClassName?: string;
  children: ReactNode | ((renderProps: DialogRenderProps) => ReactNode);
}

export interface PopoverHeaderProps {
  title: ReactNode;
  description?: ReactNode;
  className?: string;
}
```

Published usage example:

```tsx
import { RiFileCopyLine, RiLinkM, RiShareLine } from "@remixicon/react";
import { Button } from "@/components/base/buttons/button";
import { Input } from "@/components/base/input/input";
import { Popover, PopoverHeader, PopoverTrigger } from "@/components/base/popover/popover";

export function Example() {
  const url = "https://boardui.com/d/q3-revenue";
  return (
    <PopoverTrigger>
      <Button variant="secondary" leadingIcon={RiShareLine}>Share</Button>
      <Popover className="w-[360px]">
        <PopoverHeader title="Share dashboard" description="Anyone in the Acme workspace with the link can view it." />
        <div className="flex items-center gap-2">
          <Input aria-label="Dashboard link" value={url} isReadOnly inputDir="ltr" leadingIcon={RiLinkM} className="min-w-0 flex-1" />
          <Button variant="secondary" leadingIcon={RiFileCopyLine} onClick={() => navigator.clipboard.writeText(url)}>
            Copy
          </Button>
        </div>
      </Popover>
    </PopoverTrigger>
  );
}
