Combobox: captured free component source. Text field that filters a list as you type, with sections, custom values and Input's field states, built on React Aria.

Primary source: components/base/combobox/combobox.tsx. Exported names: ComboBoxProps, ComboBox, ComboBoxItemProps, ComboBoxItem, ComboBoxSectionProps, ComboBoxSection.

Declared npm dependencies: @remixicon/react@^4.9.0, react-aria-components@^1.17.0.

BoardUI registry dependencies: chevrons, cx, direction, input, scroll-fade. These names refer to source registry items, not npm packages.

Types from the primary source (referenced types may be imported):

```tsx
type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

export interface ComboBoxProps<T extends object> extends Omit<AriaComboBoxProps<T>, "children" | "className"> {
  label?: ReactNode;
  /** Help text under the field; shown in the error colour while invalid. */
  hint?: ReactNode;
  placeholder?: string;
  leadingIcon?: IconComponent;
  /** `medium` (default, 36px) or `small` (32px), as Input. */
  size?: InputSize;
  /** Shown in the list when nothing matches. */
  emptyMessage?: ReactNode;
  className?: string;
  /** Classes on the list's popover. */
  popoverClassName?: string;
  children: ReactNode | ((item: T) => ReactNode);
  ref?: Ref<HTMLDivElement>;
}

export interface ComboBoxItemProps extends Omit<AriaListBoxItemProps, "children"> {
  children?: ReactNode;
}

export interface ComboBoxSectionProps<T extends object> extends Omit<AriaListBoxSectionProps<T>, "className" | "children"> {
  /** Muted heading above the section's rows. */
  title?: ReactNode;
  className?: string;
  /** ComboBoxItems, or a React Aria Collection for a dynamic section. */
  children: ReactNode;
}
```

Published usage example:

```tsx
import { RiSearchLine } from "@remixicon/react";
import { Avatar } from "@/components/base/avatar/avatar";
import { ComboBox, ComboBoxItem } from "@/components/base/combobox/combobox";

const people = [
  { id: "maya", name: "Maya Chen", email: "maya@acme.com" },
  { id: "leo", name: "Leo Park", email: "leo@acme.com" },
  { id: "sofia", name: "Sofia Rossi", email: "sofia@acme.com" },
];

export function Example() {
  return (
    <ComboBox
      label="Assignee"
      placeholder="Search people"
      leadingIcon={RiSearchLine}
      defaultItems={people}
      defaultSelectedKey="maya"
      className="w-full max-w-[320px]"
    >
      {(person) => (
        <ComboBoxItem id={person.id} textValue={person.name}>
          <Avatar size="sm" initials={person.name[0]} />
          <span className="truncate">{person.name}</span>
          <span className="truncate text-body-2-regular text-text-tertiary">{person.email}</span>
        </ComboBoxItem>
      )}
    </ComboBox>
  );
}
