Toast: captured free component source. toast() calls from anywhere and a Toaster region that stacks them as Notification cards, with actions, updates, limits and pause on hover.

Primary source: components/base/toast/toast.tsx. Exported names: ToastId, ToastOptions, toast, ToasterProps, Toaster.

No direct npm dependencies declared by this registry item; check its BoardUI dependency closure and project requirements.

BoardUI registry dependencies: cx, notification. These names refer to source registry items, not npm packages.

Types from the primary source (referenced types may be imported):

```tsx
type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

export type ToastId = string | number;

export interface ToastOptions {
  /** Reuse an id to replace a toast that is still showing. */
  id?: ToastId;
  description?: ReactNode;
  status?: NotificationStatus;
  /** Custom leading icon; defaults to the status icon. */
  icon?: IconComponent;
  avatar?: NotificationAvatar;
  /** Small buttons under the message. Pressing one also dismisses the toast. */
  actions?: NotificationAction[];
  /** Milliseconds before it dismisses itself; `Infinity` keeps it until closed. Default from the Toaster (5000). */
  duration?: number;
  /** Show the close button. Default true. */
  dismissible?: boolean;
  /** Called once the toast has left the screen. */
  onDismiss?: () => void;
}

interface ToastRecord extends ToastOptions {
  id: ToastId;
  title: ReactNode;
  dismissed: boolean;
}

export interface ToasterProps {
  /** Edge or corner the stack is anchored to. Default `bottom-end`. */
  position?: NotificationPosition;
  /** How many toasts show at once; older ones leave as new ones arrive. Default 3. */
  limit?: number;
  /** Default countdown in milliseconds. Default 5000. */
  duration?: number;
  /** Accessible name of the region. */
  "aria-label"?: string;
  /** Accessible name of each toast's close button. */
  closeLabel?: string;
  className?: string;
}
```

Published usage example:

```tsx
// Once, near the root of the app (layout.tsx)
import { Toaster } from "@/components/base/toast/toast";

<Toaster />

// Anywhere else
import { toast } from "@/components/base/toast/toast";

toast.success("Changes saved", { description: "Your workspace settings are up to date." });

toast.info("Project archived", {
  description: "Acme Dashboard moved to the archive.",
  actions: [{ label: "Undo", onClick: () => restoreProject() }],
});

toast.error("Upload failed", { description: "Q3-report.pdf is larger than 20MB." });
